import numpy as np


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if len(x) < window_size:
        raise ValueError("Input signal shorter than window_size")
    return np.convolve(x, np.ones(window_size) / window_size, mode="valid")


def _repair(x):
    x = np.asarray(x, dtype=float).copy()
    if not np.all(np.isfinite(x)):
        f = x[np.isfinite(x)]
        v = float(np.median(f)) if f.size else 0.0
        x = np.nan_to_num(x, nan=v, posinf=v, neginf=v)
    if len(x) >= 3:
        d = np.diff(x)
        s = 1.4826 * np.median(np.abs(d - np.median(d)))
        s = max(float(s), 1e-8)
        n = 0.5 * (x[:-2] + x[2:])
        mask = np.abs(x[1:-1] - n) > 3.0 * s
        q = np.flatnonzero(mask) + 1
        x[q] = n[mask]
    return x


def _bilateral(x, radius, value_scale):
    n = len(x)
    out = np.empty(n)
    spatial = np.arange(-radius, radius + 1, dtype=float)
    sw = np.exp(-0.5 * (spatial / max(radius, 1)) ** 2)
    p = np.pad(x, (radius, radius), mode="reflect")
    for i in range(n):
        z = p[i:i + 2 * radius + 1]
        w = sw * np.exp(-0.5 * ((z - x[i]) / value_scale) ** 2)
        out[i] = np.sum(w * z) / max(np.sum(w), 1e-12)
    return out


def _score(y, source):
    d = np.diff(y)
    rev = np.count_nonzero(d[1:] * d[:-1] < 0)
    dd = np.diff(y, n=2)
    sd = np.diff(source)
    base = np.mean(sd * sd) + 1e-12
    curv = np.mean(dd * dd) / base
    res = np.mean((source - y) ** 2) / (np.var(source) + 1e-12)
    return 0.58 * rev + 0.27 * curv + 0.15 * min(res, 2.0)


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if len(x) < window_size:
        raise ValueError("Input signal shorter than window_size")
    if window_size < 3:
        return x.copy()

    z = _repair(x)
    d = np.diff(z)
    scale = 1.4826 * np.median(np.abs(d - np.median(d)))
    scale = max(float(scale), 1e-6)

    candidates = []
    try:
        from scipy.signal import savgol_filter

        widths = sorted(set([
            max(5, 2 * (window_size // 3) + 1),
            max(7, 2 * (window_size // 2) + 1),
            max(9, 2 * (window_size // 2) + 3),
        ]))
        for w in widths:
            if w < len(z):
                for p in (2, 3):
                    if p < w:
                        candidates.append(savgol_filter(z, w, p, mode="interp"))
    except Exception:
        pass

    for radius, mult in ((2, 1.5), (3, 2.5)):
        candidates.append(_bilateral(z, radius, max(scale * mult, 1e-6)))

    if not candidates:
        y = z
    else:
        y = min(candidates, key=lambda q: _score(q, z))

    return np.asarray(y[window_size - 1:], dtype=float)


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean += 0.1 * t * np.sin(0.2 * t)
    clean += np.cumsum(rng.randn(length) * 0.05)
    return clean + rng.normal(0, noise_level, length), clean


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean = generate_test_signal(
            signal_length, noise_level
        )
    else:
        clean = None
    y = process_signal(noisy_signal, window_size, "enhanced")
    if clean is None:
        return {
            "filtered_signal": y, "clean_signal": None,
            "noisy_signal": None, "correlation": 0,
            "noise_reduction": 0, "signal_length": len(y)
        }

    k = window_size - 1
    c = clean[k:k + len(y)]
    n = np.asarray(noisy_signal)[k:k + len(y)]
    m = min(len(y), len(c))
    y, c, n = y[:m], c[:m], n[:m]
    corr = np.corrcoef(y, c)[0, 1] if m > 1 else 0.0
    before = np.var(n - c)
    after = np.var(y - c)
    return {
        "filtered_signal": y,
        "clean_signal": c,
        "noisy_signal": n,
        "correlation": corr,
        "noise_reduction": (before - after) / before if before > 0 else 0.0,
        "signal_length": m,
    }


if __name__ == "__main__":
    r = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {r['correlation']:.3f}")
    print(f"Noise reduction: {r['noise_reduction']:.3f}")
    print(f"Processed signal length: {r['signal_length']}")

